use std::sync::mpsc;
use std::thread::ThreadId;

struct Sem {
    n: std::sync::Mutex<SemState>,
    cv: std::sync::Condvar,
}

struct SemState {
    permits: u32,
    owner: Option<ThreadId>,
    count: u32,
