            c.count -= 1;
            if c.count == 0 {
                c.owner = None;
                c.permits += 1;
                self.cv.notify_one();
            }
        } else {
            c.permits += 1;
            self.cv.notify_one();
        }
    }
}

fn main() {
    let (tx, rx) = mpsc::sync_channel::<u32>(0);
    let s = std::sync::Arc::new(Sem::new(1));
    let s1 = std::sync::Arc::clone(&s);
    let tx1 = tx.clone();
    let w1 = std::thread::spawn(move || {
        s1.acq();
        s1.acq();
        s1.rel();
        s1.rel();
        let _ = tx1;
        let _ = rx;
    });
    let s2 = std::sync::Arc::clone(&s);
    let w2 = std::thread::spawn(move || {
        s2.acq();
        s2.rel();
    });
    w1.join().unwrap();
    w2.join().unwrap();
    println!("DONE done=1");
}
